const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const formidable = require('formidable');

class MulterError extends Error {
  constructor(code, field) {
    super(code);
    this.name = 'MulterError';
    this.code = code;
    this.field = field;
    if (code === 'LIMIT_FILE_SIZE') {
      this.message = 'File too large';
    } else if (code === 'LIMIT_UNEXPECTED_FILE') {
      this.message = 'Unexpected field';
    } else {
      this.message = code;
    }
    Error.captureStackTrace(this, MulterError);
  }
}

function diskStorage(opts = {}) {
  const getDestination = typeof opts.destination === 'function'
    ? opts.destination
    : (req, file, cb) => cb(null, opts.destination || os.tmpdir());

  const getFilename = typeof opts.filename === 'function'
    ? opts.filename
    : (req, file, cb) => {
        const ext = path.extname(file.originalname || '');
        const randomName = crypto.randomBytes(16).toString('hex');
        cb(null, `${randomName}${ext}`);
      };

  return {
    _isDisk: true,
    getDestination,
    getFilename,
  };
}

function memoryStorage() {
  return {
    _isMemory: true,
  };
}

function multer(options = {}) {
  const storage = options.storage || diskStorage();
  const fileFilter = options.fileFilter || ((req, file, cb) => cb(null, true));
  const limits = options.limits || {};
  const maxFileSize = limits.fileSize || 50 * 1024 * 1024;

  function handleSingle(fieldName) {
    return function singleMiddleware(req, res, next) {
      const contentType = req.headers['content-type'] || '';
      if (!contentType.includes('multipart/form-data')) {
        return next();
      }

      const tempDir = path.join(os.tmpdir(), 'velvet-upload-tmp');
      if (!fs.existsSync(tempDir)) {
        try {
          fs.mkdirSync(tempDir, { recursive: true });
        } catch (_) {}
      }

      const form = formidable({
        uploadDir: tempDir,
        maxFileSize: maxFileSize,
        multiples: true,
        keepExtensions: true,
      });

      form.parse(req, async (err, fields, files) => {
        if (err) {
          // Formidable 2.x error codes: 1009 is maxFileSize exceeded
          const errMsg = String(err.message || '').toLowerCase();
          if (err.code === 1009 || err.httpCode === 413 || errMsg.includes('maxfilesize') || errMsg.includes('limit')) {
            return next(new MulterError('LIMIT_FILE_SIZE', fieldName));
          }
          return next(err);
        }

        // Populate req.body with parsed text fields
        req.body = req.body || {};
        for (const [key, val] of Object.entries(fields)) {
          req.body[key] = Array.isArray(val) && val.length === 1 ? val[0] : val;
        }

        // Find file for the expected fieldName
        const fileKeys = Object.keys(files);
        if (fileKeys.length === 0) {
          req.file = undefined;
          return next();
        }

        // Check for unexpected fields
        const unexpectedKey = fileKeys.find((k) => k !== fieldName);
        if (unexpectedKey) {
          // Clean up temp files
          for (const key of fileKeys) {
            const fList = Array.isArray(files[key]) ? files[key] : [files[key]];
            for (const f of fList) {
              if (f && f.filepath && fs.existsSync(f.filepath)) {
                try { fs.unlinkSync(f.filepath); } catch (_) {}
              }
            }
          }
          return next(new MulterError('LIMIT_UNEXPECTED_FILE', unexpectedKey));
        }

        let rawFile = files[fieldName];
        if (Array.isArray(rawFile)) {
          rawFile = rawFile[0];
        }

        if (!rawFile) {
          req.file = undefined;
          return next();
        }

        const fileObj = {
          fieldname: fieldName,
          originalname: rawFile.originalFilename || rawFile.name || 'file',
          encoding: '7bit',
          mimetype: rawFile.mimetype || 'application/octet-stream',
          size: rawFile.size,
          path: rawFile.filepath,
        };

        // Run fileFilter
        fileFilter(req, fileObj, async (filterErr, acceptFile) => {
          if (filterErr) {
            if (rawFile.filepath && fs.existsSync(rawFile.filepath)) {
              try { fs.unlinkSync(rawFile.filepath); } catch (_) {}
            }
            return next(filterErr);
          }

          if (acceptFile === false) {
            if (rawFile.filepath && fs.existsSync(rawFile.filepath)) {
              try { fs.unlinkSync(rawFile.filepath); } catch (_) {}
            }
            req.file = undefined;
            return next();
          }

          // Move to target storage destination
          if (storage && storage.getDestination && storage.getFilename) {
            storage.getDestination(req, fileObj, (destErr, dest) => {
              if (destErr) {
                if (rawFile.filepath && fs.existsSync(rawFile.filepath)) {
                  try { fs.unlinkSync(rawFile.filepath); } catch (_) {}
                }
                return next(destErr);
              }

              if (!fs.existsSync(dest)) {
                try {
                  fs.mkdirSync(dest, { recursive: true });
                } catch (mkdirErr) {
                  return next(mkdirErr);
                }
              }

              storage.getFilename(req, fileObj, (fnErr, finalFilename) => {
                if (fnErr) {
                  if (rawFile.filepath && fs.existsSync(rawFile.filepath)) {
                    try { fs.unlinkSync(rawFile.filepath); } catch (_) {}
                  }
                  return next(fnErr);
                }

                const targetPath = path.join(dest, finalFilename);

                try {
                  // If temp file is on same volume, rename; otherwise copy and unlink
                  try {
                    fs.renameSync(rawFile.filepath, targetPath);
                  } catch (renameErr) {
                    fs.copyFileSync(rawFile.filepath, targetPath);
                    try { fs.unlinkSync(rawFile.filepath); } catch (_) {}
                  }

                  req.file = {
                    fieldname: fieldName,
                    originalname: fileObj.originalname,
                    encoding: fileObj.encoding,
                    mimetype: fileObj.mimetype,
                    destination: dest,
                    filename: finalFilename,
                    path: targetPath,
                    size: fileObj.size,
                  };

                  next();
                } catch (ioErr) {
                  next(ioErr);
                }
              });
            });
          } else {
            // Default: keep in temp path
            req.file = fileObj;
            next();
          }
        });
      });
    };
  }

  function handleArray(fieldName, maxCount = 10) {
    return function arrayMiddleware(req, res, next) {
      next();
    };
  }

  function handleFields(fields) {
    return function fieldsMiddleware(req, res, next) {
      next();
    };
  }

  function handleNone() {
    return function noneMiddleware(req, res, next) {
      next();
    };
  }

  function handleAny() {
    return function anyMiddleware(req, res, next) {
      next();
    };
  }

  return {
    single: handleSingle,
    array: handleArray,
    fields: handleFields,
    none: handleNone,
    any: handleAny,
  };
}

multer.diskStorage = diskStorage;
multer.memoryStorage = memoryStorage;
multer.MulterError = MulterError;

module.exports = multer;
